"Βλέπετε την εφαρμογή ως άλλος χρήστης. Τον κωδικό του τον αλλάζει μόνο ο ίδιος, ή εσείς από το Settings → Users.": "Вы видите приложение как другой пользователь. Пароль может сменить только он сам или вы в Settings → Users.",
