"Η επωνυμία, ο ΑΦΜ και το υποσέλιδο έρχονται από τα Στοιχεία εταιρείας.": "Название, ИНН и колонтитул берутся из «Данные компании».",
"Η εταιρεία ζητά κωδικό μίας χρήσης σε κάθε σύνδεση. Ρυθμίστε τον μία φορά (2 λεπτά) για να συνεχίσετε.": "Компания требует одноразовый код при каждом входе. Настройте его один раз (2 минуты), чтобы продолжить.",
"Η εφαρμογή μπαίνει στο κινητό σαν κανονική εφαρμογή, με εικονίδιο στην αρχική οθόνη — χωρίς App Store και χωρίς κόστος.": "Приложение устанавливается на телефон как обычное, со значком на главном экране — без App Store и бесплатно.",
