"Η ημερομηνία παράδοσης φαίνεται στην ενότητα «Handover». Θα σας ειδοποιήσουμε για το ραντεβού παράδοσης.": "Дата передачи указана в разделе «Handover». Мы сообщим вам о встрече для передачи.",
