"Η νέα μονάδα παίρνει τα ίδια: τύπο, m², υπνοδωμάτια, τιμή, χώρους, προδιαγραφές και πεδία. Ξεκινά «Διαθέσιμη», χωρίς αγοραστή, φωτογραφίες ή έγγραφα.": "Новый объект получает тот же тип, м², спальни, цену, помещения, спецификации и поля. Он создаётся «Доступным», без покупателя, фото и документов.",
