"Ιστοσελίδα": "Сайт",
"Ισχύει για κάθε μονάδα, εκτός αν της ορίσετε δικό της στη σελίδα της. Όταν μια κράτηση γίνει συμβόλαιο, οι δόσεις δημιουργούνται αυτόματα από εδώ.": "Действует для каждого объекта, если на его странице не задан свой. Когда бронь становится договором, взносы создаются автоматически отсюда.",
"Ισχύει για κάθε φωτογραφία που ανεβαίνει, ακόμη κι αν το υδατογράφημα είναι κλειστό.": "Действует для каждого загружаемого фото, даже если водяной знак выключен.",
"Ισχύει και με την αυτόματη ανάθεση κλειστή.": "Действует и при выключенном автоназначении.",
"Ισχύει σε κάθε νέο κωδικό: όταν δημιουργείτε χρήστη, όταν του βάζετε κωδικό, και όταν τον αλλάζει ο ίδιος.": "Действует для каждого нового пароля: при создании пользователя, при установке ему пароля и когда он меняет его сам.",
"Ισχύει στη σελίδα κράτησης προβολής και στις φόρμες της ιστοσελίδας. «Στη φόρμα» = το πεδίο εμφανίζεται στον πελάτη· «Υποχρεωτικό» = η αποστολή δεν γίνεται όσο είναι κενό.": "Действует на странице бронирования просмотра и в формах сайта. «В форме» = поле показывается клиенту; «Обязательно» = нельзя отправить, пока оно пустое.",
"Ισχύει στη φόρμα «Νέο lead» / νέα επαφή. Με τον διακόπτη το πεδίο γίνεται υποχρεωτικό — η φόρμα δεν αποθηκεύεται όσο είναι κενό. Το όνομα χρειάζεται πάντα και δεν εμφανίζεται εδώ.": "Действует в форме «Новый лид» / новый контакт. Переключатель делает поле обязательным — форма не сохранится, пока оно пустое. Имя обязательно всегда и здесь не показано.",
"Ισχύει όταν το lead έρχεται χωρίς υπεύθυνο (φόρμες, Meta, WhatsApp, ή όταν δεν διαλέξετε στη «Νέο lead»).": "Действует, когда лид приходит без ответственного (формы, Meta, WhatsApp или если вы не выбрали его в «Новый лид»).",
"Ισχύουν για όλους ως προεπιλογή. Το πλάτος και η πυκνότητα του περιεχομένου ρυθμίζονται και στην": "По умолчанию действуют для всех. Ширина и плотность содержимого также настраиваются в",
"Ισόγειο": "Первый этаж",
"Ιταλία": "Италия",
"Κάθε πρωί: νέα leads, αναπάντητα, καθυστερήσεις σταδίου, follow-ups και ξεναγήσεις της μέρας. Κανάλια: Ρυθμίσεις → Ειδοποιήσεις.": "Каждое утро: новые лиды, без ответа, задержки этапов, follow-ups и просмотры дня. Каналы: Settings → Уведомления.",
"Κάθε πρωί: νέα, αναπάντητα, καθυστερήσεις, follow-ups και ξεναγήσεις της μέρας.": "Каждое утро: новые, без ответа, задержки, follow-ups и просмотры дня.",
"Κάθε σειρά αριθμείται χωρίς κενά: ο αριθμός δίνεται τη στιγμή της έκδοσης, και αν κάτι αποτύχει δεν χάνεται. Το": "Каждая серия нумеруется без пропусков: номер присваивается в момент выдачи и не теряется при сбое. Значение",
