"Στείλτε μου νέα για νέα έργα και προσφορές. Μπορώ να διαγραφώ οποιαδήποτε στιγμή.": "Присылайте мне новости о новых проектах и предложениях. Я могу отписаться в любой момент.",
"Στείλτε το στο προσωπικό και στους πελάτες. Ο καθένας συνδέεται με το δικό του email και βλέπει μόνο ό,τι του επιτρέπει ο ρόλος του (προσωπικό → εφαρμογή, αγοραστές / ιδιοκτήτες / επενδυτές / εργολάβοι → το portal τους).": "Отправьте её сотрудникам и клиентам. Каждый входит со своим email и видит только то, что позволяет его роль (сотрудники → приложение, покупатели / владельцы / инвесторы / подрядчики → свой портал).",
