"Στη σύνδεση εμφανίζεται «Να με θυμάται αυτή η συσκευή»: εκεί δεν ξαναζητείται κωδικός για 30 μέρες. Κάθε νέα συσκευή θέλει τον κωδικό. Ο χρήστης βλέπει και ανακαλεί τις συσκευές του.": "При входе показывается «Запомнить это устройство»: на нём код не запрашивается 30 дней. Каждому новому устройству нужен код. Пользователь видит и отзывает свои устройства.",
