"Τα email φεύγουν με αυτό το όνομα και οι απαντήσεις έρχονται σε αυτή τη διεύθυνση.": "Письма уходят с этим именем, а ответы приходят на этот адрес.",
"Τα payslips μου": "Мои расчётные листки",
"Τα αποτελέσματα που μπορεί να έχει ένα lead όταν δεν προχωρά. Με «Κουμπί» εμφανίζεται ως κουμπί ενός κλικ δίπλα στο «Κλείσιμο (Won)»· τα υπόλοιπα είναι στο «Άλλος λόγος…». Στο Lead Management κάθε αποτέλεσμα έχει δική του ενότητα, και μετρά στο «Γιατί χάνονται».": "Результаты, которые может иметь лид, если он не продвигается. С «Кнопкой» отображается как кнопка в один клик рядом с «Закрыто (успех)»; остальные — в «Другая причина…». В Lead Management у каждого результата свой раздел, и он учитывается в «Почему теряем».",
"Τα βήματα WhatsApp / email / τηλεφωνήματος των Ρυθμίσεων· σταματά όταν απαντήσει ο πελάτης.": "Шаги WhatsApp / email / звонков из настроек; останавливается, когда клиент отвечает.",
