"Τα δικά σας στοιχεία, ασφάλεια, logs και προτιμήσεις. Οι ρυθμίσεις της εταιρείας είναι στο Settings.": "Ваши данные, безопасность, журналы и настройки. Настройки компании — в Settings.",
"Τα δικαιώματα του admin δεν αλλάζουν.": "Права администратора не меняются.",
"Τα μηνύματα SMS, email και push χρειάζονται τη συγκατάθεση του πελάτη. Ενεργοποιήστε τα μόνο αν η φόρμα εγγραφής ή το συμβόλαιό σας τη ζητά.": "Для SMS, email и push нужно согласие клиента. Включайте, только если этого требует ваша форма регистрации или договор.",
"Τα νέα εισερχόμενα (φόρμες, Meta, WhatsApp, κράτηση προβολής) πριν μπουν στο pipeline. Αναθέστε, βάλτε label και «Μετατροπή σε deal».": "Новые входящие (формы, Meta, WhatsApp, запись на показ) до попадания в воронку. Назначьте, добавьте метку и «Преобразовать в сделку».",
