"Φτιάξτε όσα στάδια θέλετε, με δικά σας ονόματα και σειρά (σύρετε από τις τελίτσες ⋮⋮). Για Lost / Δεν ενδιαφέρεται διαλέξτε στο «Σημαίνει» → «Κλείσιμο χωρίς πώληση». Το «Σημαίνει» λέει στο σύστημα τι είναι το στάδιο (για αυτοματισμούς, αναφορές και προμήθειες). Η πιθανότητα μετρά στις προβλέψεις· αν ένα lead μείνει περισσότερες μέρες από το όριο, φαίνεται «σε καθυστέρηση» και ο υπεύθυνος ειδοποιείται.": "Создавайте сколько угодно этапов, со своими названиями и порядком (перетаскивайте за ⋮⋮). Для Lost / Не заинтересован выберите «Означает» → «Закрыто без продажи». «Означает» говорит системе, что это за этап (для автоматизаций, отчётов и комиссий). Вероятность учитывается в прогнозах; если лид задерживается дольше лимита, он помечается «просрочен», и ответственный получает уведомление.",
