"Χρειάζεται πρώτα η αλλαγή στη βάση (migration 0057).": "Сначала нужно изменение в базе (migration 0057).",
"Χρειάζεται πρώτα η αλλαγή στη βάση για τα τιμολόγια (migration 0056 — αρχείο supabase/ΕΚΚΡΕΜΕΙ_ΣΤΗ_ΒΑΣΗ.sql).": "Сначала нужно изменение в базе для счетов (migration 0056 — файл supabase/ΕΚΚΡΕΜΕΙ_ΣΤΗ_ΒΑΣΗ.sql).",
