"Χωρίς επαφή {} μέρες": "Без контакта {} дн.",
"Ποσοστό και τελευταίες φωτογραφίες από το εργοτάξιο.": "Прогресс и последние фото со стройки.",
"Ανοιχτά leads που ταιριάζουν σε αυτή τη μονάδα: προϋπολογισμός, περιοχή που θέλουν (σε σχέση με την τοποθεσία του έργου), έργο που προτιμούν και ό,τι ζητούν στα πεδία της μονάδας (θέα, επίπλωση κ.λπ.){}.": "Открытые лиды, подходящие этому объекту: бюджет, желаемый район (относительно расположения проекта), предпочитаемый проект и запросы по полям объекта (вид, мебель и т.д.){}.",
