"Γράψτε μήνυμα.": "Напишите сообщение.",
"Απάντηση στο ticket: {}": "Ответ на тикет: {}",
"Άκυρη κατάσταση.": "Недопустимый статус.",
"Δεν επιτρέπεται.": "Не разрешено.",
"Πώς αλλάζω τον κωδικό μου;": "Как сменить пароль?",
"Ο λογαριασμός μου → Πληροφορίες → Ασφάλεια → «Αλλαγή» δίπλα στον κωδικό.": "Мой аккаунт → Информация → Безопасность → «Изменить» рядом с паролем.",
"Πώς αλλάζω γλώσσα;": "Как сменить язык?",
"Από το εικονίδιο πάνω δεξιά ή από Ο λογαριασμός μου → Πληροφορίες → Γλώσσα. Η επιλογή ισχύει μόνο για εσάς.": "Через значок справа вверху или Мой аккаунт → Информация → Язык. Выбор действует только для вас.",
"Πώς αποσυνδέομαι;": "Как выйти?",
"Πατήστε τη φωτογραφία σας πάνω δεξιά και επιλέξτε «Αποσύνδεση», ή Ο λογαριασμός μου → Αποσύνδεση.": "Нажмите на своё фото справа вверху и выберите «Выйти», или Мой аккаунт → Выход.",
"Πού βλέπω τα νέα leads;": "Где посмотреть новые лиды?",
"Στα «Νέα leads» κάτω από το Lead management. Πατήστε «Ανάθεση σε μένα» και το lead μπαίνει στο pipeline σας.": "В «Новых лидах» в разделе Lead management. Нажмите «Назначить мне», и лид попадёт в вашу воронку.",
"Πού είναι τα follow-ups μου;": "Где мои follow-up?",
"Στα «Follow-ups»: καθυστερημένα, σήμερα και επόμενα, με κλήση και ολοκλήρωση με ένα κλικ.": "В «Follow-ups»: просроченные, сегодня и предстоящие — звонок и завершение в один клик.",
"Πώς γίνεται ένα οικόπεδο έργο;": "Как участок становится проектом?",
"Αγορά γης → Deal Analyzer → «Μετατροπή σε έργο». Τα στοιχεία της ανάλυσης περνούν στο νέο έργο.": "Покупка земли → Deal Analyzer → «Преобразовать в проект». Данные анализа переходят в новый проект.",
"Πού βλέπω το ιστορικό μιας μονάδας;": "Где посмотреть историю объекта?",
"Στη σελίδα της μονάδας: κράτηση, πώληση, ιδιοκτήτες, ενοικιάσεις, πληρωμές, συντήρηση και έγγραφα.": "На странице объекта: бронь, продажа, владельцы, аренда, платежи, обслуживание и документы.",
"Κάτι δεν δουλεύει — τι κάνω;": "Что-то не работает — что делать?",
"Ανοίξτε ένα ticket από «Τα tickets μου». Ο διαχειριστής ειδοποιείται αμέσως και απαντά εκεί.": "Откройте тикет в «Мои тикеты». Администратор сразу получит уведомление и ответит там.",
"Νέος λογαριασμός και ρυθμίσεις": "Новый аккаунт и настройки",
"Ο λογαριασμός μου και οι Ρυθμίσεις στήθηκαν από την αρχή, πιο καθαρά.": "Мой аккаунт и Настройки переделаны с нуля и стали понятнее.",
"Tickets υποστήριξης με συνομιλία": "Тикеты поддержки с перепиской",
"Αποσύνδεση από το εικονίδιο πάνω δεξιά": "Выход через значок справа вверху",
"Τρεις γλώσσες": "Три языка",
"Όλη η εφαρμογή σε ελληνικά, αγγλικά και ρώσικα.": "Всё приложение на греческом, английском и русском.",
"Καρτέλα υπαλλήλου με ημερομηνία πρόσληψης, λήξη συνεργασίας, συμβάσεις και έγγραφα.": "Карточка сотрудника с датой найма, окончанием работы, договорами и документами.",
"Το χρώμα της εταιρείας παντού": "Цвет компании везде",
"Ό,τι είναι επιλεγμένο γεμίζει με το χρώμα που διαλέγετε στις Ρυθμίσεις.": "Всё выбранное заливается цветом, выбранным в Настройках.",
"Γρήγορες απαντήσεις στις πιο συνηθισμένες ερωτήσεις": "Быстрые ответы на частые вопросы",
"Πρόσφατες αλλαγές και βελτιώσεις": "Последние обновления и улучшения",
"Η εφαρμογή αλλάζει γλώσσα αμέσως και τη θυμάται ο λογαριασμός σας.": "Приложение сразу меняет язык, и ваш аккаунт его запоминает.",
"Η ζώνη ώρας ορίζεται για όλη την εταιρεία στις Ρυθμίσεις.": "Часовой пояс задаётся для всей компании в Настройках.",
"Διαλέξτε από ποια κανάλια δέχεστε ενημερώσεις marketing. Οι ειδοποιήσεις λειτουργίας (ασφάλεια, χρεώσεις, κλείδωμα λογαριασμού) έρχονται πάντα.": "Выберите, по каким каналам получать маркетинговые сообщения. Служебные уведомления (безопасность, счета, блокировка) приходят всегда.",
"Marketing μέσα στην εφαρμογή": "Маркетинг в приложении",
"Ενημερώσεις marketing μέσα στην εφαρμογή.": "Маркетинговые новости внутри приложения.",
"Email για προσφορές και νέα της εταιρείας.": "Письма о предложениях и новостях компании.",
"Ειδοποιήσεις push στο κινητό.": "Push-уведомления на телефоне.",
"Οι ειδοποιήσεις λειτουργίας (ασφάλεια, κλείδωμα, χρεώσεις, υποστήριξη) δεν απενεργοποιούνται.": "Служебные уведомления (безопасность, блокировка, счета, поддержка) отключить нельзя.",
"Αποθήκευση προτιμήσεων": "Сохранить настройки",
