"Οι συνομιλίες σας με την υποστήριξη": "Ваша переписка с поддержкой",
"Λύθηκαν": "Решено",
"Ενημέρωση": "Обновлено",
"Δεν υπάρχουν tickets ακόμη.": "Тикетов пока нет.",
"απαντήσεις": "ответов",
"Γράψτε τι χρειάζεστε — ο διαχειριστής ειδοποιείται αμέσως.": "Опишите, что вам нужно, — администратор получит уведомление сразу.",
