"Πώς παίρνουν οι πελάτες τον κωδικό μίας χρήσης όταν συνδέονται στην εφαρμογή.": "Как клиенты получают одноразовый код при входе в приложение.",
"Το email λειτουργεί μόνο αν ο πελάτης έχει email στο προφίλ του. Αν το κανάλι δεν είναι διαθέσιμο για κάποιον, χρησιμοποιείται αυτόματα το άλλο.": "Email работает, только если у клиента указан email. Если канал недоступен, автоматически используется другой.",
"Έκδοση αποδείξεων": "Выдавать квитанции",
"Κάθε πληρωμή (προκαταβολή, δόση, συντήρηση) παίρνει απόδειξη και, αν θέλετε, φεύγει αμέσως με email στον πελάτη.": "Каждый платёж (задаток, взнос, обслуживание) получает квитанцию, и при желании она сразу отправляется клиенту по email.",
"Όταν είναι κλειστό, οι νέες πληρωμές δεν παίρνουν αριθμό απόδειξης ούτε PDF.": "Если выключено, новые платежи не получают номер квитанции и PDF.",
"Αυτόματη αποστολή με email": "Отправлять автоматически по email",
"Η απόδειξη στέλνεται στον πελάτη μόλις καταχωριστεί η πληρωμή.": "Квитанция отправляется клиенту сразу после регистрации платежа.",
"Γλώσσα απόδειξης": "Язык квитанции",
