"Κείμενο στο κάτω μέρος": "Текст внизу",
"π.χ. Ευχαριστούμε για την προτίμηση.": "напр. Спасибо, что выбрали нас.",
"Πληρωμές με κάρτα μέσω της σελίδας πληρωμής της Viva. Τα χρήματα πάνε στον δικό σας λογαριασμό Viva.": "Оплата картой через страницу Viva. Деньги поступают на ваш счёт Viva.",
"Ο δικός σας λογαριασμός JCC. Οι πελάτες πληρώνουν στη σελίδα πληρωμής της JCC.": "Ваш собственный счёт JCC. Клиенты платят на странице оплаты JCC.",
"Ο δικός σας λογαριασμός Stripe. Οι πελάτες πληρώνουν στη σελίδα checkout της Stripe.": "Ваш собственный счёт Stripe. Клиенты платят на странице checkout Stripe.",
"Νόμισμα": "Валюта",
"Τιμές, πωλήσεις, αποδείξεις και η εφαρμογή πελάτη χρησιμοποιούν αυτό το νόμισμα.": "Цены, продажи, квитанции и приложение клиента используют эту валюту.",
"Πληρωμές στην εφαρμογή μέσω {}": "Оплата в приложении через {}",
"Αν το ενεργοποιήσετε, απενεργοποιούνται οι πληρωμές μέσω των άλλων παρόχων.": "Если включить, оплата через других провайдеров отключается.",
"Για ασφάλεια, τα κλειδιά των παρόχων δεν γράφονται εδώ — τα βάζει ο προγραμματιστής στον server. Μόλις μπουν, η κάρτα δείχνει «Συνδεδεμένο».": "В целях безопасности ключи провайдеров здесь не вводятся — их добавляет разработчик на сервере. После этого карточка покажет «Подключено».",
"Ρύθμιση βοηθού": "Настройка ассистента",
"Ανάλυση leads, προτάσεις για deals, πρόχειρα μηνύματα και η ημερήσια ενημέρωση στο Dashboard.": "Анализ лидов, советы по сделкам, черновики сообщений и ежедневная сводка на Dashboard.",
"Atlas AI ενεργό": "Atlas AI включён",
"Όταν είναι κλειστό, κρύβονται οι προτάσεις AI σε όλη την εφαρμογή.": "Если выключено, подсказки AI скрыты во всём приложении.",
"Ημερήσια ενημέρωση": "Ежедневная сводка",
"Η κάρτα «Καλημέρα» στο Dashboard με ό,τι χρειάζεται προσοχή.": "Карточка «Доброе утро» на Dashboard с тем, что требует внимания.",
"Γλώσσα απαντήσεων": "Язык ответов",
"Ύφος": "Стиль",
"Σύντομο": "Кратко",
"Αναλυτικό": "Подробно",
"Το κλειδί του μοντέλου AI το βάζει ο προγραμματιστής στον server. Μέχρι τότε οι λειτουργίες AI δείχνουν απλούς κανόνες.": "Ключ модели AI добавляет разработчик на сервере. До тех пор функции AI работают по простым правилам.",
"Μπορείτε να αποσυνδεθείτε από αυτή τη συσκευή οποιαδήποτε στιγμή.": "Вы можете выйти на этом устройстве в любой момент.",
"Συγχρονισμός ραντεβού και ξεναγήσεων με το ημερολόγιο κάθε συνεργάτη.": "Синхронизация встреч и показов с календарём каждого сотрудника.",
"Ιδιωτικότητα & ασφάλεια": "Конфиденциальность и безопасность",
"Σύνδεση, κωδικοί, συσκευές, διατήρηση δεδομένων και GDPR": "Вход, пароли, устройства, хранение данных и GDPR",
"Κωδικός σύνδεσης": "Код входа",
