"Οι συντελεστές ΦΠΑ για πωλήσεις, υπηρεσίες και τιμολόγια": "Ставки НДС для продаж, услуг и счетов",
"Διάταξη, αρίθμηση και αυτόματη αποστολή με email, με ζωντανή προεπισκόπηση": "Макет, нумерация и автоматическая отправка по email с живым предпросмотром",
"Νόμισμα και πληρωμές με κάρτα": "Валюта и оплата картой",
"Ρύθμιση του βοηθού AI": "Настройка AI-ассистента",
"Μία γραμμή ανά μονάδα. Μπορείτε να σβήσετε στήλες που δεν χρειάζεστε ή να αφήσετε κενά κελιά. Η πρώτη γραμμή πρέπει να έχει τις επικεφαλίδες. Δουλεύουν και τα δικά σας ονόματα στηλών: στην εισαγωγή διαλέγετε σε ποιο πεδίο πάει η καθεμία.": "Одна строка на объект. Можно удалить ненужные столбцы или оставить ячейки пустыми. В первой строке должны быть заголовки. Свои названия столбцов тоже подходят: при импорте вы выбираете, в какое поле идёт каждый.",
