"Ό,τι έρχεται από φόρμες, Meta, WhatsApp ή κράτηση προβολής εμφανίζεται εδώ μέχρι να το αναλάβει κάποιος.": "Всё, что приходит из форм, Meta, WhatsApp или записи на просмотр, появляется здесь, пока кто-то не возьмёт лид.",
