"Καλωσόρισμα πελατών": "Приветствие клиентов",
"Καλωσόρισμα ομάδας": "Приветствие команды",
"Το μήνυμα που θα δουν": "Сообщение, которое они увидят",
"Νέο έργο — δείτε τις πρώτες μονάδες": "Новый проект — смотрите первые объекты",
"Το κείμενό σας εδώ.": "Ваш текст здесь.",
"νέα leads": "новые лиды",
"Μήνυμα της διοίκησης προς την ομάδα.": "Сообщение руководства команде.",
"Τι βλέπουν οι πελάτες σας και η ομάδα σας στο κινητό: αρχική οθόνη, περιεχόμενο και ρυθμίσεις.": "Что видят ваши клиенты и команда на телефоне: главный экран, контент и настройки.",
"Επαναφορά προεπιλογής": "Сбросить по умолчанию",
"Σύρετε από τη λαβή για να αλλάξετε σειρά. Τίποτα δεν φτάνει στο κινητό μέχρι να πατήσετε «Αποθήκευση διάταξης».": "Перетащите за ручку, чтобы изменить порядок. Ничего не попадёт на телефон, пока вы не нажмёте «Сохранить макет».",
"Ποια έργα εμφανίζονται στην εφαρμογή πελατών, με ποια σειρά (σύρσιμο) και με ποια σύντομη περιγραφή.": "Какие проекты показываются в приложении клиентов, в каком порядке (перетаскивание) и с каким кратким описанием.",
"Η εφαρμογή μπαίνει στο κινητό σαν κανονική εφαρμογή, χωρίς App Store και χωρίς κόστος. Στείλτε το link στους πελάτες και στην ομάδα.": "Приложение устанавливается на телефон как обычное, без App Store и бесплатно. Отправьте ссылку клиентам и команде.",
