"Ειδοποιήσεις ανά θέμα": "Уведомления по темам",
"Ποια γεγονότα ενημερώνουν την ομάδα σας και με ποιο κανάλι. Πατήστε ένα θέμα για να διαλέξετε κανάλια ανά γεγονός.": "Какие события уведомляют вашу команду и по какому каналу. Нажмите тему, чтобы выбрать каналы для каждого события.",
"Νέα leads, αναθέσεις, αναπάντητα, προβολές και κρατήσεις": "Новые лиды, назначения, неотвеченные, просмотры и брони",
"Αιτήματα ιδιοκτητών, συντήρηση, εγγυήσεις και ενημερώσεις κατασκευής": "Запросы владельцев, обслуживание, гарантии и обновления строительства",
"Καθυστερημένες πληρωμές, εργολάβοι και προθεσμίες ΦΠΑ": "Просроченные платежи, подрядчики и сроки НДС",
"Εργασίες, άδειες, μισθοδοσία, συμβάσεις και προμήθειες": "Задачи, отпуска, зарплата, договоры и комиссии",
"Άμεσα μηνύματα προς την ομάδα": "Личные сообщения команде",
