"Ειδοποιήσεις πληρωμών": "Уведомления о платежах",
"Πολιτική λογαριασμού: τι μαθαίνουν οι αγοραστές για τις δόσεις τους.": "Политика аккаунта: что покупатели узнают о своих платежах.",
"Αποστολή ειδοποιήσεων πληρωμών": "Отправлять уведомления о платежах",
"Απενεργοποιημένο = δεν στέλνεται τίποτα στους αγοραστές για πληρωμές.": "Выкл. = покупателям ничего не отправляется о платежах.",
"Δόση πλησιάζει": "Скоро платёж",
