"Από 1 έως 30 μέρες.": "От 1 до 30 дней.",
"Οι ειδοποιήσεις πληρωμών ελέγχονται μία φορά τη μέρα το πρωί. Τα SMS χρεώνονται ανά μήνυμα από τον πάροχο SMS.": "Уведомления о платежах проверяются раз в день утром. SMS оплачиваются поштучно у SMS-провайдера.",
"Ευχές γενεθλίων": "Поздравления с днём рождения",
"Στέλνονται στους πελάτες τη μέρα των γενεθλίων τους (μόνο σε όσους δέχονται μηνύματα στο κανάλι).": "Отправляются клиентам в день рождения (только тем, кто согласен получать сообщения по каналу).",
"Αποστολή ευχών γενεθλίων": "Отправлять поздравления",
"Ένα μήνυμα τον χρόνο σε κάθε πελάτη με ημερομηνία γέννησης στην καρτέλα του.": "Одно сообщение в год каждому клиенту с датой рождения в карточке.",
